<style>
	div {
		/* U+00A0 glued to the property stays glued: one ident to css-syntax, a separator to parseCss */
		color   :  red;

		/* an ASCII space ahead of the run is a token separator and is kept, as one space */
		top      : 0;

		/* in a comment-bearing gap, on either side of the comment */
		left    /* comment */   :   0;

		right   /* comment */    :  0;
	}
</style>
